//! Real common admission/owner/receipt/drain/prefix/CAS path, no inference.
use super::*;
use std::fs;
use crate::pet_runtime::{continuation::Captured,leases::DrainOutcome};
fn now()->u64{crate::assistant_memory::now()}
fn two_steps(s:&Setup,to:&str)->(Record,Record,crate::pet_runtime::messages::Receipt){
 let sender=if to=="ai_ollama"{"ai_lmstudio"}else{"ai_ollama"};let(p,o)=pool_to_allowance(s,sender,to,vec![crate::pet_runtime::criteria::NATIVE_MESSAGE_CRITERION.into()],1,budget(),Allowance{model_calls:0,tool_calls:2,output_bytes:8192});let a=approve(s,&p,&o,0);let r=o.send_message(&p,&a,now(),||s.observe()).unwrap();let g=own_draft(s,&r);let st=current_store(s);let g=st.mutate(&g.id,to,&g.revision,"second-own-task".into(),Action::ProposeTask{description:"Second original bounded peer operation".into()},now()).unwrap().record;let first=g.plans[0].steps[0].clone();let g=st.mutate(&g.id,to,&g.revision,"second-own-plan".into(),Action::ProposePlan{task_id:g.tasks.last().unwrap().id.clone(),steps:vec![StepInput{description:first.description,postcondition:first.postcondition,operation:first.operation}]},now()).unwrap().record;(p,g,r)
}
fn send(s:&Setup,g:&Record,o:&Owned,index:usize)->crate::pet_runtime::messages::Receipt{
 let p=&g.plans[index];let step=&p.steps[0];let a=crate::pet_runtime::messages::Input::parse(step.operation.as_ref().unwrap()).unwrap();let target=Arc::new(Target::capture(&s.config,&s.settings,a.to_pet()).unwrap());let t=now();let approved=o.review_message(g,&p.id,&step.id,nonce().unwrap(),target,t).unwrap().approve(o,g,&s.config,&s.settings,t,Arc::new(||true)).unwrap();o.send_message(g,&approved,now(),||s.observe()).unwrap()
}
fn partial(s:&Setup,to:&str)->(Record,Record,crate::pet_runtime::messages::Receipt,crate::pet_runtime::messages::Receipt){
 let(p,g,r)=two_steps(s,to);let a=approved(s,&g,child_budget(&r),nonce().unwrap());let c=s.a.certify(&a,&g,now()).unwrap();let q=current_store(s).enqueue_certified(&c,now()).unwrap().record;let(g,o)=crate::pet_runtime::deterministic_runtime_tests::owned(&s.f,&s.a,&q,&s.main);let first=send(s,&g,&o,0);let st=current_store(s);let paused=crate::pet_runtime::authority_store::mutate_with_authority(&st,&s.f.path.join("authority"),&g.id,to,&g.revision,nonce().unwrap(),Action::Pause,now()).unwrap().record;let d=o.drain(DrainOutcome::Confirmed).unwrap();let closed=st.drain_owned(&s.a,&d,now()).unwrap().record;assert_eq!(closed.state,State::Paused);assert_eq!(closed.id,paused.id);drop(o);(p,closed,r,first)
}
fn captured(s:&Setup,g:&Record)->Captured{current_store(s).prepare_continuation_review(&s.f.path.join("authority"),&g.id,&g.spec.owner.pet_id,&g.revision,now(),false).unwrap().unwrap().1}
fn next(s:&Setup,g:&Record,b:Budget)->AdmissionReview{let t=now();AdmissionReview::prepare_deterministic_continuation(g,crate::pet_runtime::deterministic_runtime_tests::evidence(g,t),b,captured(s,g),nonce().unwrap(),nonce().unwrap(),t).unwrap()}
fn accepted(s:&Setup,g:&Record,r:&crate::pet_runtime::messages::Receipt)->crate::pet_runtime::admission::Approved{let v=next(s,g,child_budget(r));assert_eq!(v.proposal().continuation.as_ref().unwrap().schema_version,8);assert!(!v.proposal().continuation.as_ref().unwrap().additional_allowance);v.approve(g,crate::pet_runtime::deterministic_runtime_tests::evidence(g,now()),now()).unwrap()}
fn bytes(s:&Setup,g:&Record)->Vec<u8>{fs::read(s.f.path.join("authority").join(format!("{}.json",g.admissions.last().unwrap().spec.decision_id))).unwrap()}
fn settle(s:&Setup,p:&Record,r:&crate::pet_runtime::messages::Receipt)->crate::pet_runtime::authority_store::delegation::View{Authority::existing(&s.f.path.join("authority")).unwrap().prepare_delegation_branch(p.clone(),&p.admissions[0].spec.decision_id,&r.envelope().message_id,crate::pet_runtime::delegation::BranchAction::Reconcile,now()).unwrap().confirm(now(),Arc::new(||true)).unwrap().view}
#[test]fn funded_tool_continuation_reuses_original_receipt_only_charges_missing_step_and_settles_once_for_seven_pets(){
 for pet in["agent_codex","agent_copilot","agent_antigravity","ai_ollama","ai_lmstudio","ai_openai","integration_spotify"]{
  let mut s=Setup::new();s.settings.active_integrations=s.config.pets.keys().cloned().collect();let(p,g,r,first)=partial(&s,pet);let old=bytes(&s,&g);let approved=accepted(&s,&g,&r);assert_eq!(approved.spec().schema_version,16);assert_eq!(approved.spec().funding.as_ref().unwrap().schema_version,4);let carry=approved.spec().continuation.as_ref().unwrap();assert_eq!(carry.charge.tool_calls,1);assert_eq!(carry.native.as_ref().unwrap().receipts.len(),1);let c=s.a.certify(&approved,&g,now()).unwrap();let q=current_store(&s).enqueue_certified(&c,now()).unwrap().record;assert_eq!(q.schema_version,36);let pb:Value=serde_json::from_slice(&s.bytes(&p)).unwrap();assert_eq!(pb["body"]["schemaVersion"],27);assert_eq!(pb["body"]["delegationReservations"][0]["schemaVersion"],5);
  let(g,o)=crate::pet_runtime::deterministic_runtime_tests::owned(&s.f,&s.a,&q,&s.main);assert!(o.review_message(&g,&g.plans[0].id,&g.plans[0].steps[0].id,nonce().unwrap(),Arc::new(Target::capture(&s.config,&s.settings,&r.envelope().origin.pet_id).unwrap()),now()).is_err());let second=send(&s,&g,&o,1);assert_ne!(first.envelope().message_id,second.envelope().message_id);let progress=o.verify_native_goal(&current_store(&s),&g).unwrap();assert!(progress.report.criteria_verified&&!progress.recipient_execution_verified);assert_eq!(progress.report.receipts.len(),2);assert_eq!(progress.report.receipts.iter().filter(|r|r.source_decision_id.is_some()).count(),1);let done=progress.completion.unwrap().record;assert_eq!(done.state,State::Completed);let d=o.drain(DrainOutcome::Confirmed).unwrap();current_store(&s).drain_owned(&s.a,&d,now()).unwrap();drop(o);let done=current_store(&s).read(&done.id,pet).unwrap();assert_eq!(done.schema_version,36);let b:Value=serde_json::from_slice(&bytes(&s,&done)).unwrap();assert_eq!(b["body"]["schemaVersion"],26);assert_eq!(b["body"]["budgetUsage"]["attempts"].as_array().unwrap().len(),1);assert_eq!(fs::read(s.f.path.join("authority").join(format!("{}.json",g.admissions[0].spec.decision_id))).unwrap(),old);
  let v=settle(&s,&p,&r);assert_eq!(v.consumed.as_ref().unwrap().model_calls,0);assert_eq!(v.consumed.as_ref().unwrap().tool_calls,2);assert_eq!(v.unknown.unwrap(),Allowance::default());let after=s.bytes(&p);assert_eq!(settle(&s,&p,&r).consumed.unwrap().tool_calls,2);assert_eq!(s.bytes(&p),after);let mut old_reader=done.clone();old_reader.schema_version=29;assert!(old_reader.validate().is_err());
 }
}
#[test]fn funded_tool_continuation_cannot_mint_budget_change_deadline_or_use_model_route(){
 let s=Setup::new();let(p,g,r,_)=partial(&s,"ai_lmstudio");let original=s.bytes(&p);
 for dim in["tools","output","deadline","model"]{let mut b=child_budget(&r);match dim{"tools"=>b.max_tool_calls=2,"output"=>b.max_output_bytes=8192,"deadline"=>b.deadline_at+=1,_=>b.max_model_calls=1};let at=now();assert!(AdmissionReview::prepare_deterministic_continuation(&g,crate::pet_runtime::deterministic_runtime_tests::evidence(&g,at),b,captured(&s,&g),nonce().unwrap(),nonce().unwrap(),at).is_err(),"{dim}");assert_eq!(s.bytes(&p),original);}
 let mut spec=accepted(&s,&g,&r).spec().clone();spec.schema_version=8;assert!(!spec.binding_format());let mut spec=accepted(&s,&g,&r).spec().clone();spec.funding=None;assert!(!spec.binding_format());
}
#[test]fn funded_tool_continuation_competing_successor_and_revoked_parent_do_not_rebind_or_refund(){
 let s=Setup::new();let(p,g,r,_)=partial(&s,"ai_ollama");let a=accepted(&s,&g,&r);let b=accepted(&s,&g,&r);let c=s.a.certify(&a,&g,now()).unwrap();let after=s.bytes(&p);assert!(s.a.certify(&b,&g,now()).is_err());assert_eq!(s.bytes(&p),after);let q=current_store(&s).enqueue_certified(&c,now()).unwrap().record;
 let cancel=Authority::existing(&s.f.path.join("authority")).unwrap().prepare_delegation_branch(p.clone(),&p.admissions[0].spec.decision_id,&r.envelope().message_id,crate::pet_runtime::delegation::BranchAction::Cancel,now()).unwrap().confirm(now(),Arc::new(||true)).unwrap();assert_eq!(cancel.stop.unwrap().binding.decision_id,q.admissions.last().unwrap().spec.decision_id);let v=settle(&s,&p,&r);assert_eq!(v.consumed.unwrap().tool_calls,1);assert_eq!(v.unknown.unwrap(),Allowance::default());assert!(s.a.verify_queued(&q,now()).is_err());
}

#[test]fn funded_tool_continuation_plan_review_preserves_delivered_input_and_revises_only_pending_data_without_authority(){
 let s=Setup::new();let(p,g,r,first)=partial(&s,"ai_ollama");let st=current_store(&s);let snapshot=crate::pet_runtime::plans::snapshot(&g);let causes:Vec<_>=snapshot.causes().collect();let mut after=snapshot.input(&causes[1]).unwrap();after.description="Explicit revised pending operation".into();after.operation.as_mut().unwrap().arguments["text"]=json!("Revised pending literal, not authority");let bad=crate::pet_runtime::native_plan_revisions::Input{cause:causes[0].clone(),after:after.clone()};let before=bytes(&s,&g);assert!(st.prepare_native_plan(&s.f.path.join("authority"),&g.id,&g.spec.owner.pet_id,&g.revision,vec![bad],nonce().unwrap(),now()).is_err());assert_eq!(bytes(&s,&g),before);
 let edit=crate::pet_runtime::native_plan_revisions::Input{cause:causes[1].clone(),after};let review=st.prepare_native_plan(&s.f.path.join("authority"),&g.id,&g.spec.owner.pet_id,&g.revision,vec![edit],nonce().unwrap(),now()).unwrap();let proposal=review.proposal().unwrap();assert!(!proposal.execution_authorized&&!proposal.budget_reserved);assert_eq!(proposal.coverage.unwrap().receipts.len(),1);let mut choice=review.approve(now(),Arc::new(||true)).unwrap();let receipt=choice.confirm(&st,now()).unwrap();assert!(receipt.acknowledged&&!receipt.execution_authorized&&!receipt.new_admission_created);let g=receipt.receipt.record;assert_eq!(g.schema_version,36);assert_eq!(g.admissions.len(),1);let b:Value=serde_json::from_slice(&bytes(&s,&g)).unwrap();assert_eq!(b["body"]["schemaVersion"],26);let old:Value=serde_json::from_slice(&before).unwrap();assert_eq!(b["body"]["budgetUsage"],old["body"]["budgetUsage"]);let a=accepted(&s,&g,&r);assert_eq!(a.spec().continuation.as_ref().unwrap().schema_version,8);assert_eq!(a.spec().continuation.as_ref().unwrap().plan_revision.as_ref().unwrap().schema_version,1);let c=s.a.certify(&a,&g,now()).unwrap();let q=st.enqueue_certified(&c,now()).unwrap().record;let(g,o)=crate::pet_runtime::deterministic_runtime_tests::owned(&s.f,&s.a,&q,&s.main);let second=send(&s,&g,&o,1);assert!(second.envelope().text.starts_with("Revised pending literal"));assert_ne!(first.envelope().message_id,second.envelope().message_id);assert!(o.verify_native_goal(&st,&g).unwrap().report.criteria_verified);let d=o.drain(DrainOutcome::Confirmed).unwrap();st.drain_owned(&s.a,&d,now()).unwrap();assert_eq!(settle(&s,&p,&r).consumed.unwrap().tool_calls,2);
}

#[test]fn native_peer_funded_continuation_reuses_carried_receipt_and_only_drives_the_missing_step(){
 let mut s=Setup::new();s.settings.active_integrations=s.config.pets.keys().cloned().collect();let(_parent,g,r,first)=partial(&s,"integration_spotify");let old=bytes(&s,&g);let(config,settings)=s.observe().unwrap();let observe:crate::pet_runtime::native_peer_plan::Observe=Arc::new(move||Ok((config.clone(),settings.clone())));let review=next(&s,&g,child_budget(&r));let at=now();let review=review.with_native_peer_plan(&g,&s.f.path.join("goals"),&s.f.path.join("authority"),observe,Some(crate::pet_runtime::planning::Start::WhenAvailable),at).unwrap();let policy=review.proposal().native_peer_plan.unwrap();assert_eq!(policy.steps.len(),1);
 let approved=review.approve_with_scopes(&g,crate::pet_runtime::deterministic_runtime_tests::evidence(&g,at),None,Some(crate::pet_runtime::disclosure_consent::Consent::BoundedNativePeerPlan),at).unwrap();let c=s.a.certify(&approved,&g,now()).unwrap();let q=current_store(&s).enqueue_certified(&c,now()).unwrap().record;assert_eq!(q.admissions.last().unwrap().spec.schema_version,16);let(leased,o)=crate::pet_runtime::deterministic_runtime_tests::owned(&s.f,&s.a,&q,&s.main);let(driver,status)=crate::pet_runtime::native_peer_plan::tests::run_with(&s.f,o,s.config.clone(),s.settings.clone());assert_eq!(status.phase,crate::pet_runtime::lease_controller::dispatcher::Phase::Completed);drop(driver);let done=current_store(&s).read(&leased.id,"integration_spotify").unwrap();assert_eq!(s.a.native_completion(&done.admissions.last().unwrap().spec,done.admissions.last().unwrap().proof.as_ref().unwrap()).unwrap().unwrap().receipts.iter().filter(|r|r.message_id==first.envelope().message_id).count(),1);assert_eq!(std::fs::read(s.f.path.join("authority").join(format!("{}.json",g.admissions[0].spec.decision_id))).unwrap(),old);
}
